"""Reference warehouse / Xbox actions checked in actual solo and networked PIE."""
import json,time
from pathlib import Path
from run_acceptance import *
results=[]
def test(name,predicate,seconds=12):
 try:d=wait_for(predicate,seconds)
 except AssertionError as error:
  Path('Saved/WarehouseQA/failure.txt').write_text(str(error));raise AssertionError(name+'; see Saved/WarehouseQA/failure.txt') from None
 results.append({'name':name,'passed':True,'observed':d});Path('Saved/WarehouseQA/acceptance.json').write_text(json.dumps(results,indent=2));print('PASS',name,flush=True);return d
def owned(d,index):
 identity=player(d,index)['playerId'];return next(p for w in d['worlds'] for p in w['pawns'] if p['local'] and p['playerId']==identity)
def live(w):return [g for g in w['grenades'] if not g['exploded']]
try:
 stop();call(project_tool,'open_map',map_name='Warehouse');start(1)
 test('new warehouse has six ropes, four connected vent runs and one merc entrance',lambda d:len(d['worlds'])==1 and 'Warehouse' in server(d)['map'] and server(d)['ropes']==6 and server(d)['vents']==4 and server(d)['mercDoors']==1)
 test('dense reference layout supplies over three hundred climbable crates',lambda d:server(d)['crates']>300)
 test('vent geometry fits crouched spy and blocks crouched merc',lambda d:server(d)['spyVentClear'] and server(d)['mercVentBlocked'])
 action(0,'warehouse_rope');time.sleep(.5);pad(0,'a')
 test('A mounts the spy onto a real rope',lambda d:local_pawn(d)['onRope'])
 d=report();z=local_pawn(d)['z'];time.sleep(.5);test('neutral stick holds position on rope',lambda d:local_pawn(d)['onRope'] and abs(local_pawn(d)['z']-z)<30)
 # Hold until observed travel, then release. A render/streaming hitch must not
 # turn a functionality check into an accidental 1.2-second speed benchmark.
 action(0,'pad_move_down')
 try:d=test('left stick climbs upward',lambda d:local_pawn(d)['onRope'] and local_pawn(d)['z']>z+100,4)
 finally:action(0,'pad_move_up')
 high=local_pawn(d)['z'];action(0,'pad_back_down')
 try:test('left stick climbs downward',lambda d:local_pawn(d)['onRope'] and local_pawn(d)['z']<high-45,4)
 finally:action(0,'pad_back_up')
 pad(0,'b');test('B drops and restores ordinary movement',lambda d:not local_pawn(d)['onRope'] and local_pawn(d)['traversal']==0 and local_pawn(d)['z']<105)
 pad(0,'role');action(0,'warehouse_rope');time.sleep(.5);pad(0,'a')
 test('merc can jump by rope without latching or grappling',lambda d:not local_pawn(d)['spy'] and not local_pawn(d)['onRope'] and local_pawn(d)['z']>110,3)
 test('merc lands after ordinary jump',lambda d:local_pawn(d)['z']<105)
 action(0,'traverse');test('server rejects merc traversal request',lambda d:not local_pawn(d)['onRope'] and local_pawn(d)['traversal']==0)
 pad(0,'role');action(0,'warehouse_rope');time.sleep(.5);pad(0,'a');action(0,'pad_move_down');wait_for(lambda d:local_pawn(d)['inVent'] and not local_pawn(d)['onRope'],25);action(0,'pad_move_up')
 test('rope top automatically crouches spy into overhead vent',lambda d:local_pawn(d)['inVent'] and local_pawn(d)['crouched'] and not local_pawn(d)['onRope'] and local_pawn(d)['z']>800,10)
 test('vent camera stays close rather than clipping through roof',lambda d:local_pawn(d)['cameraDistance']<115)
 action(0,'pad_back_down')
 deadline=time.monotonic()+7
 while local_pawn(report())['y']>-1380 and time.monotonic()<deadline:time.sleep(.02)
 action(0,'pad_back_up');pad(0,'a')
 test('spy can remount rope from vent mouth',lambda d:local_pawn(d)['onRope'] and not local_pawn(d)['crouched'],8)
 action(0,'pad_back_down');time.sleep(1);action(0,'pad_back_up');test('top remount permits descent',lambda d:local_pawn(d)['onRope'] and local_pawn(d)['z']<750)
 pad(0,'b');test('dropping from upper rope safely exits traversal',lambda d:local_pawn(d)['traversal']==0 and local_pawn(d)['z']<105)
 pad(0,'role');action(0,'pad_gadget_down');time.sleep(.16);action(0,'pad_gadget_up')
 test('merc throw windup uses actual animation with attached grenade in both views',lambda d:local_pawn(d)['throwing'] and local_pawn(d)['mercGrenades']==2 and local_pawn(d)['equipment']['throwAsset'] and local_pawn(d)['equipment']['worldGrenadeProp'] and local_pawn(d)['equipment']['firstPersonGrenadeProp'] and local_pawn(d)['equipment']['firstPersonArms'],2)
 test('grenade leaves on release beat and spends shared stock once',lambda d:local_pawn(d)['mercGrenades']==1 and len(live(server(d)))==1)
 test('throw recovers to weapon-ready pose',lambda d:not local_pawn(d)['throwing'] and local_pawn(d)['equipment']['firstPersonWeapon'] and local_pawn(d)['equipment']['weaponReady'])
 stop();start(4)
 test('warehouse routes replicate once on four clients',lambda d:len(d['worlds'])==4 and all(w['ropes']==6 and w['vents']==4 and w['mercDoors']==1 for w in d['worlds']),25)
 test('both mercs spawn behind the single entrance',lambda d:synced(d,1,lambda p:p['y']<-2220) and synced(d,3,lambda p:p['y']<-2220))
 action(1,'pad_move_down')
 test('merc entrance opens on approach on every client',lambda d:all(w['mercDoorOpen'] for w in d['worlds']))
 test('merc respawn door permits entry into warehouse',lambda d:synced(d,1,lambda p:p['y']>-2170))
 action(1,'pad_move_up')
 action(0,'drop_miss');time.sleep(1.5)
 test('jumping beside merc never triggers an aerial knockout',lambda d:synced(d,1,lambda p:not p['knockedOut'] and p['health']==100))
 action(0,'drop_covered');time.sleep(1.4)
 test('solid cover between falling spy and merc prevents knockout',lambda d:synced(d,1,lambda p:not p['knockedOut'] and p['health']==100))
 action(0,'clear_drop_cover');time.sleep(.5);action(0,'drop_attack')
 test('spy landing from above knocks merc unconscious without killing',lambda d:synced(d,1,lambda p:p['knockedOut'] and p['health']==100 and p['capsuleHalfHeight']<40),5)
 test('unconscious merc body stays visibly above floor on every client',lambda d:synced(d,1,lambda p:p['knockedOut'] and p['knockoutRemaining']<4.7 and 0<p['headZ']<95 and p['pelvisZ']>0),4)
 pad(1,'rt');pad(1,'gadget');pad(1,'a')
 test('unconscious merc cannot fire, throw or jump',lambda d:synced(d,1,lambda p:p['knockedOut'] and p['mercGrenades']==2) and synced(d,2,lambda p:p['health']==100) and all(not live(w) for w in d['worlds']))
 test('knockout naturally recovers movement, body capsule and weapon',lambda d:synced(d,1,lambda p:not p['knockedOut'] and not p['recoveryShield'] and p['health']==100 and p['capsuleHalfHeight']>80 and p['equipment']['weaponReady']),12)
 action(0,'drop_attack');test('second valid aerial landing knocks out recovered merc',lambda d:synced(d,1,lambda p:p['knockedOut']),5)
 action(1,'damage');test('death during knockout clears unconscious state',lambda d:synced(d,1,lambda p:p['health']==0 and not p['knockedOut']))
 test('knocked-out merc respawns standing with restored controls and supplies',lambda d:synced(d,1,lambda p:p['health']==100 and not p['knockedOut'] and p['capsuleHalfHeight']>80 and p['mercGrenades']==2),15)
 action(2,'warehouse_rope');time.sleep(.7);pad(2,'a');test('remote spy mounts rope on all clients',lambda d:synced(d,2,lambda p:p['onRope']))
 action(0,'network_lag');action(2,'pad_move_down');wait_for(lambda d:synced(d,2,lambda p:p['inVent'] and not p['onRope']),25);action(2,'pad_move_up')
 test('remote climb and vent entry converge under lag and packet loss',lambda d:synced(d,2,lambda p:p['inVent'] and p['crouched'] and not p['onRope']) and aligned(d,2),15)
 action(0,'network_reset');test('spy remains crouched in vent',lambda d:synced(d,2,lambda p:p['crouched']))
 assert 'firing lane' in action(0,'warehouse_vent_shot');time.sleep(.8);pad(1,'rt')
 test('merc gunfire passes through vent sheet metal and damages spy',lambda d:synced(d,2,lambda p:p['health']==66))
 action(2,'damage');test('dead vent spy respawns with no stuck traversal',lambda d:synced(d,2,lambda p:p['health']==100 and not p['onRope'] and not p['inVent']),15)
 action(2,'warehouse_rope');time.sleep(.6);pad(2,'a');action(2,'pad_move_down');time.sleep(.8);action(2,'pad_move_up');action(2,'damage')
 test('death during rope climb clears movement state on all clients',lambda d:synced(d,2,lambda p:p['health']==0 and not p['onRope']))
 test('climbing spy respawns normally',lambda d:synced(d,2,lambda p:p['health']==100 and p['traversal']==0),15)
 action(1,'warehouse_rope');time.sleep(.6);action(1,'pad_gadget_down');time.sleep(.16);action(1,'pad_gadget_up')
 test('remote throw animates owner arms and replicated world body before release',lambda d:synced(d,1,lambda p:p['throwing'] and p['mercGrenades']==2 and p['equipment']['worldGrenadeProp']) and owned(d,1)['equipment']['firstPersonArms'],3)
 test('remote prop remains attached to both animated hand sockets',lambda d:owned(d,1)['equipment']['worldGrenadeGrip']<5 and owned(d,1)['equipment']['firstPersonGrenadeGrip']<5)
 test('remote throw releases one replicated grenade',lambda d:synced(d,1,lambda p:p['mercGrenades']==1) and all(len(live(w))==1 for w in d['worlds']))
 test('remote throw restores both weapon views',lambda d:synced(d,1,lambda p:not p['throwing']) and owned(d,1)['equipment']['firstPersonWeapon'])
 test('thrown grenade expires before next fixture',lambda d:all(not live(w) for w in d['worlds']),7)
 action(0,'warehouse_noise');time.sleep(.8);action(2,'pad_move_down');time.sleep(.9);action(2,'pad_move_up')
 test('merc sound-direction cue comes from audible emitted spy steps',lambda d:owned(d,1)['noiseAge']<1.2)
 action(1,'damage');test('merc death respawns behind same entrance',lambda d:synced(d,1,lambda p:p['health']==100 and p['y']<-2220 and p['mercGrenades']==2),15)
 print(json.dumps({'passed':len(results),'total':len(results)}),flush=True)
finally:
 stop();call(project_tool,'open_map',map_name='Warehouse');start(1);action(0,'automation_off')
